package env

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
)

var publishedPort = regexp.MustCompile(`^\s*-\s*"(\$\{[A-Z_]+:-[^}]*\}|\d+):\d+"\s*$`)

// TestComposePortsBindLoopbackAndImagesArePinned keeps the control stack off the network: a
// published port names its bind host, and the gateway image (it holds the provider keys) is pinned by digest.
func TestComposePortsBindLoopbackAndImagesArePinned(t *testing.T) {
	files, _ := filepath.Glob(filepath.Join("..", "..", "stacks", "compose.*.yaml"))
	if len(files) == 0 {
		t.Skip("not running inside the repository")
	}
	for _, f := range files {
		data, err := os.ReadFile(f)
		if err != nil {
			t.Fatal(err)
		}
		for i, line := range strings.Split(string(data), "\n") {
			if publishedPort.MatchString(line) {
				t.Errorf("%s:%d publishes a port on every interface: %s", filepath.Base(f), i+1, strings.TrimSpace(line))
			}
			if strings.Contains(line, "image:") && strings.Contains(line, "litellm") && !strings.Contains(line, "@sha256:") {
				t.Errorf("%s:%d must pin the LiteLLM image by digest: %s", filepath.Base(f), i+1, strings.TrimSpace(line))
			}
		}
	}
}

func TestRedisPasswordIsAManagedSecret(t *testing.T) {
	for _, k := range ManagedSecrets {
		if k == "REDIS_PASSWORD" {
			return
		}
	}
	t.Fatal("REDIS_PASSWORD must be generated by 'secrets ensure'")
}
